const KEY='reels-start-v1';
let storageUnavailable=false;
function readState(){try{return KadrState.normalize(JSON.parse(localStorage.getItem(KEY)))}catch{storageUnavailable=true;return KadrState.normalize({})}}
let state=readState(),saved=structuredClone(state),current='home',toastTimer;
const app=document.querySelector('#app');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{let raw;try{raw=JSON.parse(localStorage.getItem(KEY))}catch{raw=null}const remote=KadrState.normalize(raw);state=KadrState.merge(saved,state,remote);localStorage.setItem(KEY,JSON.stringify(state));saved=structuredClone(state);storageUnavailable=false;return true}catch{toast('Не удалось сохранить на устройстве. Скачай карточку ответов.');storageUnavailable=true;return false}}
function toast(t){const e=document.querySelector('#toast');clearTimeout(toastTimer);e.textContent=t;e.classList.add('show');toastTimer=setTimeout(()=>e.classList.remove('show'),3500)}
const missions=[['Выбери свой аккаунт','Найди точку, с которой начнёшь.','АККАУНТ'],['Проверь его состояние','Узнай исходные условия.','ДИАГНОСТИКА'],['Собери настройки','Пройди экраны по образцу.','НАСТРОЙКИ'],['Реши, что оставить','Разберись со старыми публикациями.','ПРОФИЛЬ'],['Дай причину остаться','Собери имя и описание блога.','ОФОРМЛЕНИЕ'],['Сохрани точку старта','Зафиксируй данные для сравнения.','СТАРТ']];
const field=(key,label,placeholder='',type='text')=>`<label class="field">${label}<input data-field="${key}" type="${type}" ${type==='number'?'min="0" step="1"':''} value="${esc(state.fields[key])}" placeholder="${placeholder}"></label>`;
const area=(key,label,placeholder='')=>`<label class="field">${label}<textarea data-field="${key}" placeholder="${placeholder}">${esc(state.fields[key])}</textarea></label>`;
const select=(key,label,options)=>`<label class="field">${label}<select data-field="${key}" aria-label="${label}"><option value="">Выбери вариант</option>${options.map(o=>`<option ${state.fields[key]===o?'selected':''}>${o}</option>`).join('')}</select></label>`;
const detail=(title,body)=>`<details><summary>${title}</summary><p>${body}</p></details>`;
const check=(key,text)=>`<label class="check"><input type="checkbox" data-field="${key}" ${state.fields[key]?'checked':''}>${text}</label>`;
const block=(title,body)=>`<section class="content-block"><h3>${title}</h3>${body}</section>`;
const prompt=()=>`Помоги оформить мой блог. Имя: ${state.fields.name||'[имя]'}. Темы: ${state.fields.topics||'[темы]'}. Формат: ${state.fields.format||'[с лицом / без лица]'}. Подача: ${state.fields.tone||'[манера общения]'}.\nПредложи три варианта поля имени и три описания до 150 символов с пробелами каждое. Сделай понятным, какой контент получит подписчик. Не придумывай квалификацию, достижения и результаты. Не представляй меня экспертом без оснований. Пиши естественно, без пафоса. Добавь простой призыв подписаться. Я отдельно проверю длину готового текста.`;
const paths={map:'M4 6l5-2 6 2 5-2v14l-5 2-6-2-5 2V6zm5-2v14m6-12v14',bag:'M5 8h14l1 12H4L5 8zm4 0V6a3 3 0 016 0v2',award:'M8 3h8l3 6-7 5-7-5 3-6zm1 10-2 8 5-3 5 3-2-8',user:'M16 7a4 4 0 11-8 0 4 4 0 018 0zM4 21v-2a8 8 0 0116 0v2',star:'M12 3l2.8 5.7 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.6l6.2-.9L12 3z',check:'M5 12l4 4L19 6',play:'M8 4l12 8-12 8V4z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3zm-4 9 3 3 5-6',sliders:'M5 4v16M12 4v16M19 4v16M2 9h6m1 7h6m1-9h6',archive:'M4 8h16v12H4V8zm-1-5h18v5H3V3zm6 9h6',pen:'M4 20l1-6L16 3l5 5-11 11-6 1zm9-14 5 5',flag:'M5 21V3m0 1c5-4 9 4 15 0v10c-6 4-10-4-15 0',lock:'M6 10h12v11H6V10zm3 0V6a3 3 0 016 0v4',bolt:'M13 2L4 14h7l-1 8 10-13h-7l0-7',chevron:'M9 5l7 7-7 7',book:'M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2V4zm9 2v15',calendar:'M4 5h16v16H4V5zm3-3v6m10-6v6M4 11h16',sound:'M4 9h4l5-5v16l-5-5H4V9zm12-2q6 5 0 10',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
const navs=[['home','map','Путь'],['materials','bag','Рюкзак'],['achievements','award','Награды'],['help','shield','Помощь'],['profile','user','Профиль']];
state.activity ||= {}; state.goal ||= 1;
const dayKey=()=>KadrState.dateKey();
const todayCount=()=>state.activity[dayKey()]||0;
const rank=()=>state.done.length>=42?'Автор со своей системой':state.done.length>=24?'Создатель контента':state.done.length>=6?'Исследователь':'Начинающий автор';
const nodeIcons=['user','shield','sliders','archive','pen','flag'];
function navRender(){const view=typeof current==='number'||String(current).startsWith('chapter/')?'home':current;for(const id of ['mainNav','mobileNav'])document.querySelector('#'+id).innerHTML=navs.map(([v,i,t])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${v==='home'?'<small>7 глав</small>':''}</button>`).join('');document.querySelector('#xpStat').innerHTML=icon('bolt')+'<b>'+state.done.length*50+'</b> XP';}
function home(){let n=state.done.length,active=next();app.innerHTML=`<div class="dashboard"><div class="journey-column"><section class="world-banner"><div class="world-banner-copy"><div class="chapter-chip">МИР 01 <span>СТУДИЯ</span></div><h1>Всё начинается<br>с первого кадра.</h1><p>Собери основу своего блога.<br>Шесть миссий - и ты готов к следующему шагу.</p><button id="chapters" class="world-select">Точка старта ${icon('chevron')}</button></div><img src="assets/studio.svg" class="studio-art" alt="Иллюстрация творческой студии с рабочим столом и камерой"><span class="banner-spark spark-a"><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg></span><span class="banner-spark spark-b">+</span></section><div class="map-toolbar"><div><span class="tiny">ТВОЙ МАРШРУТ</span><h2>Точка старта <span>${n}/6</span></h2></div><div class="view-switch" aria-label="Вид маршрута"><button data-mode="map" aria-pressed="${state.mapMode!=='list'}" class="${state.mapMode!=='list'?'active':''}" aria-label="Карта">${icon('map')}</button><button data-mode="list" aria-pressed="${state.mapMode==='list'}" class="${state.mapMode==='list'?'active':''}" aria-label="Список">${icon('book')}</button></div></div>${state.mapMode==='list'?`<div class="mission-list">${missions.slice(0,6).map((m,i)=>`<button data-lesson="${i}" class="mission-list-row"><span class="list-orb ${state.done.includes(i)?'finished':''}">${icon(state.done.includes(i)?'check':nodeIcons[i])}</span><span><small>МИССИЯ 0${i+1}</small><b>${m[0]}</b><em>${m[1]}</em></span><span>${state.done.includes(i)?'<svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12l4 4L19 6"/></svg>':'+50 XP'}</span>${icon('chevron')}</button>`).join('')}</div>`:`<section class="world-map" aria-label="Карта из шести миссий"><div class="map-contours"></div><div class="map-label">STUDIO / 01<span>ТВОЁ НАЧАЛО ЗДЕСЬ</span></div><svg class="route" viewBox="0 0 600 900" preserveAspectRatio="none" aria-hidden="true"><path d="M270 90C270 160 410 140 410 245S230 280 230 390S390 415 390 535S235 580 235 680S300 720 300 820" fill="none" stroke="#d4cbed" stroke-width="17" stroke-linecap="round"/><path d="M270 90C270 160 410 140 410 245S230 280 230 390S390 415 390 535S235 580 235 680S300 720 300 820" fill="none" stroke="#fbf9ff" stroke-width="4" stroke-dasharray="2 16" stroke-linecap="round"/></svg><img class="world-sticker sticker-a" src="assets/stickers/clapper.svg" alt="" aria-hidden="true"><img class="world-sticker sticker-b" src="assets/stickers/idea.svg" alt="" aria-hidden="true"><img class="world-sticker sticker-c" src="assets/stickers/editor.svg" alt="" aria-hidden="true">${missions.slice(0,6).map((m,i)=>`<div class="map-stop stop-${i} ${state.done.includes(i)?'is-done':i===active?'is-current':'is-next'}">${i===active&&n<6?'<span class="start-bubble">'+(n?'ПРОДОЛЖИМ?':'СТАРТУЕМ?')+'</span>':''}<button class="node" data-lesson="${i}" aria-label="Миссия ${i+1}: ${m[0]}${state.done.includes(i)?', пройдена':''}"><span class="node-face">${icon(state.done.includes(i)?'check':nodeIcons[i])}</span><span class="node-stars">${state.done.includes(i)?'<svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg> <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg> <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg>':'0'+(i+1)}</span></button><button class="node-caption" data-lesson="${i}">${m[0]}</button>${i===active&&n<6?'<small class="node-xp">+50 XP за миссию</small>':''}</div>`).join('')}<div class="map-companion"><img src="assets/click.svg" alt="Клик"><span>${n===6?'Студия готова!':'Я рядом.<br>Всё получится.'}</span></div></section>`}<section class="next-world"><span class="next-world-icon">${icon('lock')}</span><div><small>СЛЕДУЮЩИЙ МИР</small><h3>Лаборатория идей</h3><p>Учимся замечать контент, который цепляет.</p></div><span class="soon">В разработке</span></section></div><aside class="dashboard-aside"><section class="profile-card"><div class="profile-heading"><div class="user-emblem">${icon('user')}</div><div><small>ТВОЙ УРОВЕНЬ</small><h3>${rank()}</h3></div></div><div class="level-track"><i style="width:${n/6*100}%"></i></div><div class="level-caption"><span>${n*50} XP</span><span>Цель главы · 300 XP</span></div></section><section class="quest-card"><div class="panel-heading"><span class="quest-icon">${icon('bolt')}</span><h3>Маленькая цель дня</h3></div><p>${n===6?'Все миссии главы пройдены. Можно повторить материал или открыть рюкзак.':todayCount()>=state.goal?'На сегодня цель выполнена. Отличная работа!':'Двигайся в своём темпе. Цель - '+state.goal+' '+(state.goal===1?'миссия':'миссии')+' сегодня.'}</p><div class="quest-progress"><span>${n===6?'Готово':Math.min(todayCount(),state.goal)+' / '+state.goal}</span><div><i style="width:${(n===6?1:Math.min(todayCount()/state.goal,1))*100}%"></i></div>${icon(n===6||todayCount()>=state.goal?'check':'flag')}</div><button class="primary" data-lesson="${active}">${n===6?'Повторить миссию':'Перейти к миссии'} ${icon('play')}</button><button class="quiet" data-view="profile">Настроить цель</button></section><section class="reward-preview"><div class="panel-heading"><h3>${n===6?'Все награды собраны':'Ближайшая награда'}</h3>${icon('spark')}</div><div class="badge-mini ${n>=6?'earned':''}">${icon('award')}</div><h4>${n<1?'Первый кадр':n<3?'Вошёл в ритм':'Студия готова'}</h4><p>${n<1?'Заверши первую миссию':n<3?'Пройди три миссии':'Собери все шесть шагов'}</p><button class="quiet" data-view="achievements">Все награды ${icon('chevron')}</button></section><section class="tip-card"><span class="tiny">ЗАМЕТКА ОТ КЛИКА</span><p>Не сравнивай своё начало<br>с чужой сотой попыткой.</p><div class="tip-signature">Клик <span>твой проводник</span></div></section></aside></div>`}
function legacyAchievements(){const n=state.done.length;app.innerHTML=`<section class="screen-heading"><span class="tiny">КОЛЛЕКЦИЯ ДОСТИЖЕНИЙ</span><h1>Каждый шаг имеет значение.</h1><p>Эти награды - за твою работу. Они остаются с тобой.</p></section><div class="achievement-summary"><span>${icon('bolt')} <b>${n*50}</b> опыта</span><span>${icon('award')} <b>${[1,3,6].filter(x=>n>=x).length}/3</b> награды</span><span>${icon('check')} <b>${n}/6</b> миссий</span></div><div class="badge-grid">${[[1,'play','Первый кадр','Первый шаг уже сделан. Теперь ты в игре.'],[3,'bolt','Вошёл в ритм','Три миссии позади. Основа становится крепче.'],[6,'award','Студия готова','Аккаунт настроен. Можно переходить к контенту.']].map(([limit,i,title,desc])=>`<article class="badge-card ${n>=limit?'unlocked':'locked'}"><div class="badge-art">${icon(i)}<span><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg></span><span><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/></svg></span></div><span class="badge-status">${n>=limit?'ПОЛУЧЕНО':'ЕЩЁ ВПЕРЕДИ'}</span><h2>${title}</h2><p>${desc}</p><div class="badge-track"><i style="width:${Math.min(n/limit,1)*100}%"></i></div><small>${Math.min(n,limit)} / ${limit} · ${limit===1?'миссия':'миссии'}</small></article>`).join('')}</div><section class="friendly-note"><img src="assets/click.svg" alt="Клик"><div><h3>Здесь нет гонки за первым местом.</h3><p>Опыт начисляется один раз за каждую новую миссию. Возвращаться к пройденным заданиям можно сколько угодно.</p></div></section>`}
function profile(){const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {key:KadrState.dateKey(d),label:d.toLocaleDateString('ru',{weekday:'short'}),date:d.getDate()}});app.innerHTML=`<section class="screen-heading"><span class="tiny">ТВОЁ ПРОСТРАНСТВО</span><h1>Свой темп. Свой путь.</h1><p>Настрой маленькую цель и наблюдай за своим движением.</p></section><div class="profile-layout"><section class="settings-card"><div class="big-avatar">${icon('user')}</div><h2>${esc(state.fields.displayName||'Начинающий автор')}</h2><span class="level-pill">${rank()} · ${state.done.length*50} XP</span>${field('displayName','Как тебя называть?','Твоё имя')}<p class="note">Имя сохраняется автоматически и видно только в этом браузере.</p></section><section class="settings-card"><h3>${icon('flag')} Цель на день</h3><p>Выбери посильный темп. Цель считается по впервые завершённым миссиям.</p><div class="goal-options">${[1,2,3].map(n=>`<button data-goal="${n}" aria-pressed="${state.goal===n}" class="${state.goal===n?'selected':''}"><b>${n}</b><span>${n===1?'миссия':'миссии'}</span><small>${n===1?'Спокойно':n===2?'Уверенно':'Интенсивно'}</small></button>`).join('')}</div><h3 class="activity-title">Последние 7 дней</h3><div class="activity-week">${days.map(d=>`<div><span>${d.label}</span><b class="${state.activity[d.key]?'day-done':''}">${state.activity[d.key]?'<svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12l4 4L19 6"/></svg>':d.date}</b></div>`).join('')}</div><p class="note">Отмечаем дни, когда ты завершал новые миссии. Старые отметки до обновления приложения не восстанавливаются.</p></section><section class="settings-card preferences"><div><h3>Звук награды</h3><p>Короткий сигнал при завершении новой миссии.</p></div><button role="switch" aria-checked="${!!state.sound}" id="soundToggle" class="toggle ${state.sound?'on':''}" aria-label="Звук награды"><span></span></button></section><section class="settings-card preferences"><div><h3>Твои данные</h3><p>Прогресс хранится в браузере на этом устройстве. Сохрани карточку аккаунта, чтобы иметь копию ответов.</p></div><button class="secondary" id="download">Скачать карточку ${icon('bag')}</button></section></div>`}
function playReward(){if(!state.sound)return;try{const A=window.AudioContext||window.webkitAudioContext;const ctx=new A();[523,659,784].forEach((f,i)=>{const o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=f;g.gain.setValueAtTime(0,ctx.currentTime+i*.12);g.gain.linearRampToValueAtTime(.05,ctx.currentTime+i*.12+.02);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+i*.12+.22);o.start(ctx.currentTime+i*.12);o.stop(ctx.currentTime+i*.12+.23)});setTimeout(()=>ctx.close(),800)}catch{}}
function legacyReward(i,fresh){const n=state.done.length;document.querySelector('#rewardContent').innerHTML=`<button id="closeReward" class="modal-close" aria-label="Закрыть награду"><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18"/></svg></button><div class="confetti" aria-hidden="true">${Array.from({length:16},(_,j)=>`<i style="--i:${j}"></i>`).join('')}</div><img src="assets/click.svg" class="reward-mascot" alt="Клик радуется"><span class="tiny">${fresh?'ОТЛИЧНАЯ РАБОТА':'МИССИЯ ПРОВЕРЕНА'}</span><h2>${n===6?'Студия готова!':'Ещё один шаг вперёд!'}</h2><p>${missions[i][0]} - выполнено.</p><div class="reward-points">${icon('bolt')} ${fresh?'+50 XP':'Ответы сохранены'}</div>${fresh&&[1,3,6].includes(n)?`<div class="new-badge">${icon('award')} Новая награда: ${n===1?'Первый кадр':n===3?'Вошёл в ритм':'Студия готова'}</div>`:''}<button class="primary" id="rewardContinue" data-next="${n===6?'home':next()}">${n===6?'Вернуться в студию':'Следующая миссия'} ${icon('chevron')}</button><button class="quiet" id="rewardMap">На карту</button>`;openDialog('reward');if(fresh)playReward()}
function legacyChapters(){document.querySelector('#rewardContent').innerHTML=`<button id="closeReward" class="modal-close" aria-label="Закрыть"><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 6l12 12M18 6 6 18"/></svg></button><span class="tiny">СЕМЬ МИРОВ ТВОЕГО БЛОГА</span><h2>Весь маршрут</h2><div class="chapter-index">${['Точка старта','Лаборатория идей','Тексты с ИИ','Видеобанк','Монтаж и публикация','Ритм публикаций','Анализ результатов'].map((t,i)=>`<div><span>0${i+1}</span><b>${t}</b><small>${i?'В разработке':'Доступно'}</small></div>`).join('')}</div>`;openDialog('reward')}
function next(){return [0,1,2,3,4,5].find(i=>!state.done.includes(i))??5}
const shots=[['type','Тип аккаунта','Сверь выбранный тип с моими настройками.'],['tags','Метки и упоминания','Проверь, кто может упоминать тебя.'],['reuse','Репосты и использование','Разрешения на распространение контента.'],['followers','Подписки и приглашения','Сверь настройки обработки подписок.'],['permissions','Разрешения телефона','На моём телефоне: доступ к фото разрешён.'],['quality','Качество медиа','У меня включена загрузка в самом высоком качестве.']];
function lesson(i){if(i>=6){courseLesson(i);return}current=i;state.last=i;persist();let body='',intro='',result='';
if(i===0){intro='Возможно, подходящий аккаунт уже у тебя есть. Выбери профиль, который готов использовать для блога.';result='Ник аккаунта и понятная точка входа.';body=block('Твоя задача',`<p>Рассмотри свой личный профиль или старый неиспользуемый аккаунт. Убедись, что можешь войти и восстановить доступ при необходимости.</p>${field('handle','Ник аккаунта','@my_account')}${select('accountKind','С чего начинаешь?',['Личный аккаунт','Старый неиспользуемый аккаунт','Уже публикую, меняю подход','Есть только новый аккаунт'])}${check('access','Я могу войти и имею доступ к восстановлению аккаунта')}`)+detail('Зачем начинать с существующего аккаунта?','В моей практике существующие аккаунты часто запускались лучше новых. Это наблюдение, а не гарантия охватов. Старый профиль тоже может иметь ограничения или неподходящую аудиторию - дальше проверим его состояние. Если есть только новый аккаунт, продолжать обучение можно.')+detail('Мне неловко публиковать для знакомых','Выбери профиль, которым готов регулярно пользоваться. На старте достаточно определить, какие темы и кадры комфортно показывать публично. Не нужно сразу раскрывать всю личную жизнь.')}
if(i===1){intro='Перед началом работы посмотри сообщения самой платформы. Запишем состояние, с которого начинаешь.';result='Проверенный статус и список вопросов, если они есть.';body=block('Проверь статус',`<ol><li>Открой меню профиля и раздел настроек.</li><li>Найди «Статус аккаунта».</li><li>Открой каждый доступный пункт и прочитай сообщения.</li></ol>${screenGuide('status','Статус аккаунта',1)}${select('status','Что показано у тебя?',['Ограничений не обнаружено','Есть предупреждение','Не могу найти раздел'])}${area('statusNote','Заметка о состоянии аккаунта','Что стоит проверить или исправить?')}`)+detail('Зачем это нужно?','Низкие просмотры сами по себе не объясняют причину. Проверка статуса помогает увидеть сообщения платформы и зафиксировать исходное состояние. Зелёные отметки не гарантируют рост будущих роликов.')+detail('У меня предупреждение','Открой сообщение и прочитай причину. Изучи доступные действия исправления или обжалования. Не удаляй публикации наугад. Можно продолжать читать уроки, а в твоей карточке останется выбранный ответ «Есть предупреждение».')+detail('Не могу найти раздел','Названия и расположение пунктов могут отличаться. Поищи «Статус аккаунта» в настройках. Если раздел недоступен, сохрани эту отметку и вернись к проверке позже.')}
if(i===2){intro='Пройди настройки по реальным экранам с моего телефона. Отмечай проверенные пункты - ничего не нужно держать в памяти.';result='Проверенный Центр аккаунтов и шесть групп настроек.';body=accountsCenterGuide()+visualSettings()+detail('Почему нельзя просто включить всё?','Настройки выполняют разные задачи: качество загрузки, метки, распространение контента и доступ к телефону. Большее количество включённых функций само по себе не означает готовность к продвижению.')+detail('Зачем загрузка в высоком качестве?','На моём экране включена загрузка в самом высоком качестве. Она не исправляет размытую съёмку и неудачный исходник. Качество ролика начинается до публикации.')+detail('Зачем я разрешил камеру и микрофон?','На моём актуальном скриншоте оба разрешения включены: камера нужна для съёмки внутри приложения, микрофон - для записи звука. Доступ ко всем фото позволяет выбирать готовые исходники. Контакты, геолокация и уведомления у меня запрещены - это отдельные разрешения с другими задачами.')+detail('У меня другой экран','Сверь название функции. Если нужного пункта нет, выбери «Пункт недоступен». Если назначение непонятно, выбери «Нужно разобраться», не меняя похожие настройки наугад.')}
if(i===3){intro='Начало нового этапа не требует стирать свою историю. Реши, какие публикации хочешь сохранить в профиле.';result='Выбранный способ работы со старым контентом.';body=block('Выбери свой вариант',`${select('archive','Старые публикации',['Оставляю как есть','Часть буду архивировать','Старых публикаций нет'])}<p>Чтобы изменить вид профиля, я использую <b>архивирование по 1–2 публикации в день</b> параллельно с началом новых публикаций.</p><p class="note">Выбираем именно «Архивировать», не «Удалить». Темп - моя рекомендация.</p>${area('archiveNote','Что хочешь оставить или убрать?','Например: оставить личные фото, архивировать старую рекламу')}`)+detail('Почему именно архивирование?','Я выбираю архивирование и не рекомендую массово удалять старые публикации ради нового старта. В своей практике я отношусь к массовому удалению как к лишнему риску для стабильной работы аккаунта и охватов. При этом подтверждённого правила Instagram «удаление публикаций снижает охваты или обязательно вызывает ограничения» у меня нет. Поэтому мой порядок работы - постепенно архивировать по 1-2 публикации в день, сохраняя возможность вернуть материалы. Это моя осторожная рекомендация, а не установленный платформой лимит. Перед подтверждением проверь, что выбрано именно архивирование.')+detail('Нужно сначала полностью очистить профиль?','Нет. В этом методе новые публикации и постепенное архивирование идут параллельно. Не откладывай обучение до идеального оформления.')}
if(i===4){intro='Человек заинтересовался роликом и открыл профиль. Помоги ему понять, что он найдёт здесь дальше.';result='Имя, описание и понятное направление блога.';body=block('Собери основу',`${field('name','Имя в профиле','Например: Анна · истории о семье')}${select('format','Формат',['С лицом','Без лица','Оба формата'])}${area('topics','О чём будет блог?','Например: отношения, семья и жизненные решения')}${field('tone','Как звучит твоя подача?','Спокойно и прямо, без нравоучений')}<p class="note">Поле «Имя» отображается в профиле. Ник с @ ты указал в первом шаге: это отдельное поле. В имени можно коротко обозначить тему блога.</p><p><b>Аватарка:</b> узнаваемый портрет или простой знак для блога без лица. Проверь, различим ли он в маленьком круге.</p>${check('avatar','Я выбрал читаемую аватарку')}`)+block('Напиши описание',`<p>Тема → особенность подачи → приглашение остаться.</p><p class="note">Пример: «Об отношениях, семье и непростых решениях. Истории, в которых узнаёшь себя. Оставайся, если любишь смотреть глубже».</p>${area('bio','Мой вариант описания','Текст для своего профиля')}<small id="count" aria-live="polite" style="color:${Array.from(state.fields.bio||'').length>150?'#b83d26':'#6d7066'}">${Array.from(state.fields.bio||'').length} / 150 символов</small><div class="actions"><button class="secondary" id="copyPrompt">Скопировать промпт <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></button><button class="secondary" id="copyBio">Скопировать описание</button></div>${check('profileUpdated','Я перенёс имя, аватарку и описание в профиль')}`)+detail('Если у меня пока нет ниши?','Выбери несколько связанных тем, которые действительно интересны. Это предварительное направление: позже уточнишь его по результатам. Сейчас описание должно честно объяснять, какой контент будет в блоге.')+detail('Что писать, если я не эксперт?','Говори о том, что публикуешь: наблюдения, личный опыт, истории или подборки. Не приписывай себе квалификацию и не обещай решать чужие проблемы без оснований.')+detail('Проверь описание на конкретность','Назови три будущих ролика, которые подходят под описание. Если это сложно, уточни формулировку. После ответа ИИ самостоятельно проверь текст и его длину.')}
if(i===5){intro='Сохрани исходные данные. Через несколько недель они помогут сравнить результат с собой, а не с чужой удачной публикацией.';result='Твоя карточка аккаунта готова.';body=block('Точка отсчёта',`${field('startDate','Дата начала','','date')}${field('followers','Подписчиков сейчас','0','number')}${select('trial','Пробный режим',['Есть','Нет','Пока не знаю'])}${area('startNote','Что хочешь отметить на старте?','Ожидания, трудности, особенности аккаунта')}`)+detail('Почему записываем даже маленькие цифры?','Точка старта нужна для сравнения с собой. Чужая удачная публикация не показывает весь путь автора. Свои записи помогут замечать изменения и выбирать следующие действия.')+block('Финальная сверка',`${check('finalCheck','Я проверил свои ответы и сохранил исходные показатели')}<p>Ответы сохраняются по мере заполнения. Карточка доступна в «Рюкзаке» на любом этапе.</p><p class="note">Данные хранятся в этом браузере на этом устройстве. В «Рюкзаке» можно скачать ответы для чтения или резервную копию JSON для восстановления прогресса.</p>`)}
body=firstModuleVisual(i)+body;if(i===5)body+=moduleOneReview();
app.innerHTML=`<article class="lesson"><button class="back" data-view="home"><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M20 12H4m6-6-6 6 6 6"/></svg> К оглавлению</button><div class="lesson-heading"><div><div class="eyebrow">ГЛАВА 01 <span class="divider">/</span> ШАГ ${String(i+1).padStart(2,'0')} ИЗ 06</div><h1>${missions[i][0]}</h1><p class="lead">${intro}</p></div><div class="lesson-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</div></div><div class="step-strip" aria-label="Шаги главы">${missions.slice(0,6).map((m,j)=>`<button data-lesson="${j}" class="${j===i?'current':''} ${state.done.includes(j)?'finished':''}" aria-label="Шаг ${j+1}: ${m[0]}" ${j===i?'aria-current="step"':''}><span>${state.done.includes(j)?'<svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12l4 4L19 6"/></svg>':String(j+1).padStart(2,'0')}</span><i>${m[2]}</i></button>`).join('')}</div><div class="lesson-layout"><div class="lesson-body">${body}<div class="lesson-end"><button class="primary" id="complete">${state.done.includes(i)?'Сохранить и продолжить':'Завершить шаг'} <span><svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></span></button>${i>0?`<button class="text-button" data-lesson="${i-1}">Предыдущий шаг</button>`:''}</div><p class="note">Самостоятельная практика. Отметь шаг, когда проверишь свой результат.</p></div><div class="side-note"><span class="eyebrow">ЧТО ПОЛУЧИШЬ</span><p>${result}</p><div class="side-rule"></div><span class="eyebrow">МОЖНО ГЛУБЖЕ</span><p>Открывай объяснения под заданием, чтобы разобраться в деталях.</p><span class="side-index">01 / ${String(i+1).padStart(2,'0')}</span></div></div></article>`}

function baseMaterialText(){return `МОЯ ТОЧКА СТАРТА\n\nАккаунт: ${state.fields.handle||'Не указан'}\nИмя: ${state.fields.name||'—'}\nТемы: ${state.fields.topics||'—'}\nФормат: ${state.fields.format||'—'}\nОписание: ${state.fields.bio||'—'}\nСтатус: ${state.fields.status||'—'}\nЗаметка: ${state.fields.statusNote||'—'}\nСтарые публикации: ${state.fields.archive||'—'}\nДата старта: ${state.fields.startDate||'—'}\nПодписчиков: ${state.fields.followers??'—'}\nПробный режим: ${state.fields.trial||'—'}\nМиссий пройдено: ${state.done.length}/42\n\nПодача: ${state.fields.tone||'—'}\nПлан архивации: ${state.fields.archiveNote||'—'}\nЗаметки на старте: ${state.fields.startNote||'—'}\nТип выбранного аккаунта: ${state.fields.accountKind||'Не указан'}\nЦентр аккаунтов: ${state.fields.accountsCenterReview||'Не проверено'}\n\nНастройки:\n${shots.map(([k,t])=>t+': '+(state.fields['setting_'+k]||'Не проверено')).join('\n')}`}
function baseMaterials(){app.innerHTML=`<article class="lesson"><div class="eyebrow">ВСЁ НУЖНОЕ - ПОД РУКОЙ</div><h1>Мой рюкзак<span style="color:var(--accent)">.</span></h1><p class="lead">Всё, что ты собираешь по ходу обучения, остаётся здесь.</p><div class="material-grid">${block('Карточка аккаунта',`<pre>${esc(materialText())}</pre><button class="secondary" id="download">Скачать карточку <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M12 3v12m-5-5 5 5 5-5M5 18v3h14v-3"/></svg></button>`)}${block('Описание профиля',`<p>${esc(state.fields.bio||'Здесь появится твой текст из миссии 5.')}</p><button class="secondary" data-lesson="4">${state.fields.bio?'Редактировать':'Создать описание'} <svg class="icon ui-symbol" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M6 18 18 6M6 6h12v12"/></svg></button>`)}${block('Промпт для оформления',`<pre>${esc(prompt())}</pre><button class="secondary" id="copyPrompt">Скопировать промпт</button>`)}${block('Что дальше',`<p>Референсы, хуки, описания и видеобанк появятся вместе со следующими модулями.</p><span class="pill">Сейчас доступен модуль 01</span>`)}</div></article>`}
function render(v,mode='push'){v=KadrState.route(KadrState.hash(v));const target=KadrState.hash(v);if(mode==='replace')history.replaceState(null,'',target);else if(mode==='push'&&location.hash!==target)history.pushState(null,'',target);current=v;navRender();document.body.classList.toggle('in-lesson',typeof v==='number');document.querySelector('#crumb').textContent=typeof v==='number'?'Миссия '+(v%6+1)+' / '+chapters[Math.floor(v/6)].title:({home:'Карта обучения',materials:'Мой рюкзак',achievements:'Мои награды',profile:'Мой профиль',calendar:'Календарь практики',help:'Центр помощи',preflight:'Проверка перед публикацией'}[v]||'Карта обучения');if(typeof v==='number')lesson(v);else if(v==='materials')materials();else if(v==='achievements')achievements();else if(v==='profile')profile();else if(v==='calendar')calendar();else if(v==='help')helpCenter();else if(v==='preflight')preflight();else if(String(v).startsWith('chapter/'))courseHome(Number(v.split('/')[1])-1);else courseHome(Math.floor(state.last/6));if(typeof v==='number')lessonExtras(v);app.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'})}
function invalidField(i){
 if(i>=6&&i<42){if(!String(state.fields['answer_'+i]||'').trim())return ['answer_'+i,'Запиши результат практики.'];if(!state.fields['check_'+i])return ['check_'+i,'Подтверди выполнение задания.'];return null;}
 const f=state.fields, text=k=>typeof f[k]==='string'&&f[k].trim();
 const need=(k,message)=>[k,message];
 if(i===0){if(!text('handle'))return need('handle','Укажи ник аккаунта.');if(!f.accountKind)return need('accountKind','Выбери, с какого аккаунта начинаешь.');if(!f.access)return need('access','Подтверди, что можешь войти в аккаунт.');}
 if(i===1&&!f.status)return need('status','Выбери результат проверки статуса.');
 if(i===2){if(!f.accountsCenterReview)return need('accountsCenterReview','Отметь результат проверки Центра аккаунтов.');const missing=shots.find(([k])=>!f['setting_'+k]);if(missing)return need('setting_'+missing[0],'Отметь результат проверки: '+missing[1]+'.');}
 if(i===3&&!f.archive)return need('archive','Выбери, что делать со старыми публикациями.');
 if(i===4){for(const [k,msg] of [['name','Укажи имя или название блога.'],['format','Выбери формат блога.'],['topics','Запиши темы будущего блога.'],['bio','Напиши описание профиля.']])if(!text(k))return need(k,msg);if(Array.from(f.bio).length>150)return need('bio','Сократи описание до 150 символов. Сейчас '+Array.from(f.bio).length+'.');if(!f.avatar)return need('avatar','Отметь выбор аватарки.');if(!f.profileUpdated)return need('profileUpdated','Подтверди, что перенёс оформление в профиль.');}
 if(i===5){if(!KadrState.validDate(f.startDate))return need('startDate','Укажи дату начала.');if(f.followers===undefined||String(f.followers).trim()===''||!Number.isSafeInteger(Number(f.followers))||Number(f.followers)<0)return need('followers','Укажи целое число подписчиков: 0 или больше.');if(!f.trial)return need('trial','Выбери, доступен ли пробный режим.');if(!f.finalCheck)return need('finalCheck','Подтверди проверку исходных показателей.');}
 return null;
}
function valid(i){return Number.isInteger(i)&&i>=0&&i<42&&!invalidField(i)}
function showFieldError(issue){document.querySelectorAll('[aria-invalid]').forEach(e=>{e.removeAttribute('aria-invalid');e.removeAttribute('aria-describedby')});document.querySelector('#fieldError')?.remove();const [key,message]=issue;const input=document.querySelector('[data-field="'+key+'"]');if(input){input.setAttribute('aria-invalid','true');input.setAttribute('aria-describedby','fieldError');const err=document.createElement('p');err.id='fieldError';err.className='field-error';err.setAttribute('role','alert');err.textContent=message;input.closest('label').after(err);input.focus();input.scrollIntoView({block:'center',behavior:'instant'});}toast(message)}
async function completeMission(){
 if(typeof current!=='number')return;
 const mission=current,issue=invalidField(mission);if(issue){showFieldError(issue);return}
 const button=document.querySelector('#complete');if(button.disabled)return;button.disabled=true;
 const finish=()=>{persist();const fresh=!state.done.includes(mission);if(fresh){state.done.push(mission);state.activity[dayKey()]=(state.activity[dayKey()]||0)+1;}const stored=persist();render(mission,'none');showReward(mission,fresh);if(!stored)toast('Миссия отмечена только на время сеанса. Скачай карточку.');};
 try{if(navigator.locks)await navigator.locks.request('kadr-progress',finish);else finish()}finally{if(button.isConnected)button.disabled=false}
}
function openDialog(id){const d=document.querySelector('#'+id);if(!d.open)d.showModal();const h=d.querySelector('h2');if(h){h.id='dialogTitle';h.tabIndex=-1;d.setAttribute('aria-labelledby','dialogTitle');h.focus({preventScroll:true})}}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Скопировано')}catch{toast('Копирование недоступно. Выдели текст вручную.')}}
document.addEventListener('input',e=>{if(!e.target.dataset.field)return;state.fields[e.target.dataset.field]=e.target.type==='checkbox'?e.target.checked:e.target.value;persist();document.querySelectorAll('[aria-invalid]').forEach(n=>{n.removeAttribute('aria-invalid');n.removeAttribute('aria-describedby')});document.querySelector('#fieldError')?.remove();if(e.target.dataset.field==='displayName'){document.querySelector('.settings-card h2').textContent=String(state.fields.displayName||'').trim()||'Начинающий автор';}if(e.target.dataset.field==='bio'){let n=Array.from(e.target.value).length;document.querySelector('#count').textContent=n+' / 150 символов';document.querySelector('#count').style.color=n>150?'#b83d26':'#6d7066'}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-image]');if(!el)return;if(el.dataset.view)render(el.dataset.view);if(el.dataset.lesson!==undefined)render(Number(el.dataset.lesson));if(el.id==='chapters')showChapters();if(el.dataset.mode){state.mapMode=el.dataset.mode;persist();render(current,'none')}if(el.dataset.goal){state.goal=Number(el.dataset.goal);persist();profile();toast('Цель обновлена')}if(el.id==='soundToggle'){state.sound=!state.sound;persist();profile();if(state.sound)playReward()}if(el.id==='closeReward')document.querySelector('#reward').close();if(el.id==='rewardMap'){document.querySelector('#reward').close();render('home')}if(el.id==='rewardContinue'){document.querySelector('#reward').close();render(el.dataset.next==='home'?'home':Number(el.dataset.next))}if(el.id==='complete')await completeMission();if(el.id==='copyPrompt')copy(prompt());if(el.id==='copyBio'){if(String(state.fields.bio||'').trim())copy(state.fields.bio);else toast('Сначала напиши описание профиля.');}if(el.id==='download'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([materialText()],{type:'text/plain;charset=utf-8'}));a.download='my-account.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}if(el.dataset.image){const d=document.querySelector('#lightbox');d.classList.remove('zoomed');d.querySelector('img').src=el.dataset.image;d.querySelector('img').alt=el.querySelector('img')?.alt||'Скриншот настройки';document.querySelector('#zoomImage').textContent='Увеличить';document.querySelector('#zoomImage').setAttribute('aria-pressed','false');openDialog('lightbox')}if(el.id==='zoomImage'){const z=document.querySelector('#lightbox').classList.toggle('zoomed');el.textContent=z?'Показать целиком':'Увеличить';el.setAttribute('aria-pressed',String(z));}if(el.id==='closeImage')document.querySelector('#lightbox').close()});document.querySelector('.brand').onclick=e=>{e.preventDefault();render('home')};window.addEventListener('popstate',()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());render(KadrState.route(location.hash),'none')});/* booted by course.js */if(storageUnavailable)toast('Сохранённые данные недоступны. Приложение открыто без них.');

window.addEventListener('storage',e=>{if(e.key!==KEY||!e.newValue)return;try{const previousEpoch=state.epoch;state=KadrState.merge(saved,state,JSON.parse(e.newValue));saved=structuredClone(state);navRender();if(previousEpoch!==state.epoch){document.querySelectorAll('dialog[open]').forEach(d=>d.close());render(current,'none');toast('В другой вкладке восстановлена резервная копия. Данные обновлены.')}else if(typeof current!=='number'&&current!=='profile'&&current!=='preflight'&&current!=='help'&&current!=='calendar')render(current,'none');}catch{}});

window.addEventListener('hashchange',()=>{if(location.hash!=='#app'&&KadrState.route(location.hash)!==current)render(KadrState.route(location.hash),'none')});

function moduleOneReview(){const pending=[];if(state.fields.status!=='Ограничений не обнаружено')pending.push(['Статус аккаунта: '+(state.fields.status||'не проверен'),1]);if(state.fields.accountsCenterReview!=='Один Instagram, проверено')pending.push(['Центр аккаунтов: '+(state.fields.accountsCenterReview||'не проверен'),2]);for(const [k,t] of shots)if(state.fields['setting_'+k]!=='Проверено')pending.push([t+': '+(state.fields['setting_'+k]||'не проверено'),2]);return block('Сверяю первый модуль',`<p>Завершённые шаги: ${state.done.filter(n=>n<6).length} из 6. Можно возвращаться к любому заданию и уточнять ответы.</p><div class="module-review">${missions.slice(0,5).map((m,i)=>`<button class="secondary" data-lesson="${i}">${icon(state.done.includes(i)?'check':'chevron')}${m[0]} · ${state.done.includes(i)?'завершено':'не завершено'}</button>`).join('')}</div>${pending.length?`<h4>К чему нужно вернуться</h4><p class="note">Эти отметки не мешают читать дальше. Завершение урока не снимает ограничения в Instagram.</p><ul>${pending.map(([t,i])=>`<li><button class="text-button review-link" data-lesson="${i}">${esc(t)}</button></li>`).join('')}</ul>`:'<p>Статус и все группы настроек проверены. При изменениях в аккаунте обнови ответы.</p>'}`)}
